-- create "song_charts" table
CREATE TABLE "song_charts" ("id" uuid NOT NULL, "status" character varying NOT NULL, "created_by" uuid NOT NULL, "created_at" timestamptz NOT NULL, "title" character varying NOT NULL, "artist" character varying NOT NULL, "language" character varying NOT NULL, "concert_key" character varying NULL, "capo_fret" bigint NOT NULL, "tempo_bpm" bigint NULL, "time_signature" jsonb NULL, "rights_confirmed_by" uuid NULL, "rights_confirmed_at" timestamptz NULL, "body" text NOT NULL, "warnings" jsonb NOT NULL, "updated_by" uuid NOT NULL, "updated_at" timestamptz NOT NULL, "published_revision_number" bigint NULL, "published_title" character varying NULL, "published_language" character varying NULL, "published_by" uuid NULL, "published_at" timestamptz NULL, "withdrawn_by" uuid NULL, "withdrawn_at" timestamptz NULL, "withdrawal_reason" text NULL, PRIMARY KEY ("id"));
-- create index "songchart_updated_at" to table: "song_charts"
CREATE INDEX "songchart_updated_at" ON "song_charts" ("updated_at");
-- create "song_chart_revisions" table
CREATE TABLE "song_chart_revisions" ("id" uuid NOT NULL, "revision_number" bigint NOT NULL, "title" character varying NOT NULL, "artist" character varying NOT NULL, "language" character varying NOT NULL, "concert_key" character varying NULL, "capo_fret" bigint NOT NULL, "tempo_bpm" bigint NULL, "time_signature" jsonb NULL, "tuning_fingerprint" character varying NOT NULL, "body" text NOT NULL, "rights_confirmed_by" uuid NOT NULL, "rights_confirmed_at" timestamptz NOT NULL, "published_by" uuid NOT NULL, "published_at" timestamptz NOT NULL, "song_chart_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "song_chart_revisions_song_charts_song_chart" FOREIGN KEY ("song_chart_id") REFERENCES "song_charts" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "songchartrevision_song_chart_id_revision_number" to table: "song_chart_revisions"
CREATE UNIQUE INDEX "songchartrevision_song_chart_id_revision_number" ON "song_chart_revisions" ("song_chart_id", "revision_number");
